const HEADER = "<a class=\"skip\" href=\"#main\">Skip to content</a>\n\n<!-- Reading progress. The script sets --p; a scaleX rather than a\n     width keeps the one thing that updates on every scroll frame off\n     the layout path. -->\n<div class=\"prog\" id=\"prog\" aria-hidden=\"true\"></div>\n\n<header class=\"hdr\" id=\"hdr\">\n  <div class=\"wrap hdr-in\">\n    <a class=\"brand\" href=\"{{HOME}}\" aria-label=\"BillZap home\">\n      <img src=\"/assets/icon-68.png\" alt=\"\" width=\"32\" height=\"32\" decoding=\"async\">\n      BillZap\n    </a>\n    <nav class=\"nav\" aria-label=\"Primary\">\n      <a href=\"{{BASE}}#features\">Features</a>\n      <a href=\"{{BASE}}#how\">How it works</a>\n      <a href=\"{{BASE}}#gst\">GST</a>\n      <a href=\"{{BASE}}#compare\">Compare</a>\n      <a href=\"{{BASE}}#faq\">FAQ</a>\n      <a href=\"/blog\">Blog</a>\n    </nav>\n    <a class=\"btn btn-primary btn-sm\" href=\"{{BASE}}#download\">\n      Download free <span class=\"chip\"><svg class=\"ico\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M5 12h14\" /> <path d=\"m12 5 7 7-7 7\" /></svg></span></a>\n  </div>\n</header>\n";
const FOOTER = "<footer class=\"ftr\">\n  <div class=\"wrap\">\n    <div class=\"ftr-grid\">\n      <div>\n        <div class=\"brand\">\n          <img src=\"/assets/icon-68.png\" alt=\"\" width=\"34\" height=\"34\" loading=\"lazy\" decoding=\"async\">\n          BillZap\n        </div>\n        <p>Free GST billing for Indian shops. Made for the counter, not\n           the boardroom.</p>\n      </div>\n      <div>\n        <h3>Product</h3>\n        <ul>\n          <li><a href=\"{{BASE}}#features\">Features</a></li>\n          <li><a href=\"{{BASE}}#how\">How it works</a></li>\n          <li><a href=\"{{BASE}}#languages\">Languages</a></li>\n          <li><a href=\"{{BASE}}#download\">Download</a></li>\n        </ul>\n      </div>\n      <div>\n        <h3>GST</h3>\n        <ul>\n          <li><a href=\"{{BASE}}#gst\">Compliance</a></li>\n          <li><a href=\"{{BASE}}#gst\">GSTR-1 export</a></li>\n          <li><a href=\"{{BASE}}#billing\">Tax invoices</a></li>\n          <li><a href=\"{{BASE}}#compare\">Compare</a></li>\n        </ul>\n      </div>\n      <div>\n        <h3>More</h3>\n        <ul>\n          <li><a href=\"/blog\">Blog</a></li>\n          <li><a href=\"{{BASE}}#faq\">FAQ</a></li>\n          <li><a href=\"/privacy/\">Privacy policy</a></li>\n          <li><a href=\"/llms.txt\">llms.txt</a></li>\n          <li><a href=\"https://github.com/dakshu007/billzap\" rel=\"noopener\">Source</a></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"ftr-btm\">\n      <span>\u00a9 <span id=\"yr\">2026</span> BillZap \u00b7 Free GST billing for Indian MSMEs</span>\n      <span>Works offline \u00b7 No account \u00b7 No subscription</span>\n    </div>\n  </div>\n</footer>\n";

export const header = ({ base = "/" } = {}) =>
  HEADER.replaceAll("{{HOME}}", base).replaceAll("{{BASE}}", base);
export const footer = ({ base = "/" } = {}) =>
  FOOTER.replaceAll("{{HOME}}", base).replaceAll("{{BASE}}", base);


export const head = ({ title, desc, canonical, image, ogType = 'website',
                       robots, keywords, css, ld }) => `<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${title}</title>
<meta name="description" content="${attr(desc)}">
<meta name="author" content="BillZap">
${keywords ? `<meta name="keywords" content="${attr(keywords)}">` : ''}
<meta name="robots" content="${robots}">
<link rel="canonical" href="${canonical}">
<meta name="theme-color" content="#F7F8F7">
<meta name="color-scheme" content="light">
<meta name="google-site-verification" content="4N5b9mUevn2OzdIqgR_kUHPo2D-JTpIfd1gN0cCx03s">

<meta property="og:type" content="${ogType}">
<meta property="og:site_name" content="BillZap">
<meta property="og:title" content="${attr(title)}">
<meta property="og:description" content="${attr(desc)}">
<meta property="og:url" content="${canonical}">
<meta property="og:image" content="${image || 'https://billzap.netlify.app/assets/og.png'}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:image" content="${image || 'https://billzap.netlify.app/assets/og.png'}">

<link rel="icon" href="/assets/icon-32.png" sizes="32x32" type="image/png">
<link rel="icon" href="/assets/icon-512.png" sizes="512x512" type="image/png">
<link rel="apple-touch-icon" href="/assets/icon-180.png">
<link rel="manifest" href="/site.webmanifest">
<link rel="preload" as="font" type="font/woff2" href="/assets/fonts/plus-jakarta-sans-800-latin.woff2" crossorigin>
<link rel="preload" as="font" type="font/woff2" href="/assets/fonts/poppins-400-latin.woff2" crossorigin>

<style>${css}</style>
${ld ? `<script type="application/ld+json">${JSON.stringify(ld)}</script>` : ''}
</head>`;

const attr = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/"/g, '&quot;')
  .replace(/</g, '&lt;').replace(/>/g, '&gt;');
